package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipArchiveEntry;
import org.apache.commons.compress.archivers.zip.ZipArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipMethod;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorInputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_getNextZipEntry_TriageGen2Test {

    private static final long LFH_SIG = 0x04034b50L;
    private static final long CFH_SIG = 0x06054b50L;
    private static final long AED_SIG = 0x02014b50L;

    private byte[] createLFH(int method, boolean hasDataDescriptor, String name, int compressedSize, int uncompressedSize, long crc) {
        int nameBytes = name.getBytes();
        int extraLen = 0;
        int totalSize = 30 + nameBytes.length + extraLen;
        if (hasDataDescriptor) {
            totalSize += 12; // CRC, compressed, uncompressed
        }

        ByteBuffer bb = ByteBuffer.allocate(totalSize).order(ByteOrder.LITTLE_ENDIAN);
        bb.putLong(LFH_SIG);
        bb.putShort((short) 0x0200); // Version Made By (Windows)
        bb.putShort((short) 0);      // Flags
        bb.putShort((short) method); // Method
        bb.putInt(0);                // Time

        if (!hasDataDescriptor) {
            bb.putLong(crc);
            bb.putInt(compressedSize);
            bb.putInt(uncompressedSize);
        }

        bb.putShort((short) nameBytes.length);
        bb.putShort((short) extraLen);
        bb.put(nameBytes.getBytes());

        return bb.array();
    }

    @Test
    public void testGetNextZipEntry_ClosedOrHitCentralDirectory() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);
        zis.close();
        Assert.assertNull(zis.getNextZipEntry());

        // Simulate hitCentralDirectory via a mock or by feeding CFH signature
        ByteBuffer bb = ByteBuffer.allocate(8).order(ByteOrder.LITTLE_ENDIAN);
        bb.putLong(CFH_SIG);
        ZipArchiveInputStream zis2 = new ZipArchiveInputStream(new ByteArrayInputStream(bb.array()));
        Assert.assertNull(zis2.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_EOF() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);
        Assert.assertNull(zis.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_ValidEntry_Stored() throws IOException {
        byte[] lfh = createLFH(ZipMethod.STORED.getCode(), false, "test.txt", 4, 4, 12345L);
        InputStream is = new ByteArrayInputStream(lfh);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNotNull(entry);
        Assert.assertEquals("test.txt", entry.getName());
        Assert.assertEquals(12345L, entry.getCrc());
        Assert.assertEquals(4, entry.getCompressedSize());
    }

    @Test
    public void testGetNextZipEntry_ValidEntry_DataDescriptor() throws IOException {
        // Manually construct LFH with Data Descriptor flag (bit 3)
        int nameBytes = "data.txt".getBytes().length;
        ByteBuffer bb = ByteBuffer.allocate(30 + nameBytes + 12).order(ByteOrder.LITTLE_ENDIAN);
        bb.putLong(LFH_SIG);
        bb.putShort((short) 0x0200);
        bb.putShort((short) 0x0008); // Bit 3: Data Descriptor
        bb.putShort((short) ZipMethod.STORED.getCode());
        bb.putInt(0);
        bb.putShort((short) nameBytes);
        bb.putShort((short) 0);
        bb.put("data.txt".getBytes());
        // Data descriptor follows the entry data in real stream, 
        // but the logic in getNextZipEntry reads it if flag is set.
        // The current implementation offsets 'off' but doesn't read descriptor bytes here, 
        // it just skips the header fields.

        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNotNull(entry);
        Assert.assertEquals("data.txt", entry.getName());
    }

    @Test
    public void testGetNextZipEntry_InvalidSignature() throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(8).order(ByteOrder.LITTLE_ENDIAN);
        bb.putLong(0x12345678L); // Wrong signature
        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        Assert.assertNull(zis.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_SplitArchiveSignature() throws IOException {
        // The code checks for AED_SIG/CFH_SIG in firstEntry block
        ByteBuffer bb = ByteBuffer.allocate(8).order(ByteOrder.LITTLE_ENDIAN);
        bb.putLong(AED_SIG);
        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        Assert.assertNull(zis.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_MultipleEntries() throws IOException {
        byte[] entry1 = createLFH(ZipMethod.STORED.getCode(), false, "a.txt", 1, 1, 1L);
        byte[] entry2 = createLFH(ZipMethod.STORED.getCode(), false, "b.txt", 1, 1, 2L);

        ByteBuffer bb = ByteBuffer.allocate(entry1.length + entry2.length);
        bb.put(entry1);
        bb.put(entry2);

        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        Assert.assertNotNull(zis.getNextZipEntry());
        Assert.assertEquals("a.txt", zis.getNextZipEntry().getName()); // This tests closeEntry() logic via current != null
        Assert.assertNotNull(zis.getNextZipEntry());
        Assert.assertEquals("b.txt", zis.getNextZipEntry().getName());
    }

    @Test
    public void testGetNextZipEntry_CompressionMethods() throws IOException {
        // Test Imploding (Deflated)
        byte[] lfh = createLFH(ZipMethod.IMPLODING.getCode(), false, "deflate.txt", 5, 10, 1L);
        InputStream is = new ByteArrayInputStream(lfh);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);
        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNotNull(entry);
        Assert.assertEquals(ZipMethod.IMPLODING.getCode(), entry.getMethod());

        // Test BZip2
        byte[] lfh2 = createLFH(ZipMethod.BZIP2.getCode(), false, "bzip2.txt", 5, 10, 1L);
        InputStream is2 = new ByteArrayInputStream(lfh2);
        ZipArchiveInputStream zis2 = new ZipArchiveInputStream(is2);
        ZipArchiveEntry entry2 = zis2.getNextZipEntry();
        Assert.assertNotNull(entry2);
        Assert.assertEquals(ZipMethod.BZIP2.getCode(), entry2.getMethod());
    }
}
